mapper.select:
SELECT t.id, t.project_id AS projectId, t.user_id AS userId, t.role_in_team AS roleInTeam, t.joined_at AS joinedAt, t.left_at AS leftAt, t.is_active AS isActive, t.remark, u.name AS userName, u.username AS userUsername, u.phone AS userPhone, p.name AS positionName, proj.name AS projectName FROM biz_project_team t INNER JOIN sys_user u ON t.user_id = u.id LEFT JOIN sys_position p ON u.position_id = p.id LEFT JOIN biz_project proj ON t.project_id = proj.id
AND t.project_id = #{query.projectId}
AND t.user_id = #{query.userId}
AND t.role_in_team = #{query.roleInTeam}
AND t.is_active = #{query.isActive}
ORDER BY t.is_active DESC, CASE t.role_in_team WHEN 'leader' THEN 0 WHEN 'member' THEN 1 ELSE 2 END, t.joined_at ASC, t.id ASC
